from pathlib import Path
import json
from urllib.parse import urlencode
import numpy as np
import pandas as pd
from source_io import fetch

SOURCE_URL = 'https://data-usfs.hub.arcgis.com/api/download/v1/items/810d6a45daf441e9bdb5838ef080366b/csv?layers=0'
REST_URL = 'https://apps.fs.usda.gov/arcx/rest/services/EDW/EDW_FireOccurrenceFIRESTAT_YRLY_01/MapServer/0/query'
TARGET = 'large_fire'
ID_COL = 'OBJECTID'
TIME_COL = 'DISCOVERY'
PRESCRIBED = 'PRESCRIBED_FIRE'
TOTAL = 'TOTAL_ACRES_BURNED'
NUMERIC_FEATURES = ['POO_LATITUDE', 'POO_LONGITUDE', 'SLOPE', 'ELEVATION']
CATEGORICAL_FEATURES = ['STATE_CODE', 'REPORT_UNIT_NAME', 'DISTRICT', 'OWNERSHIP_AGENCY_AT_ORIGIN', 'PROTECTING_AGENCY_AT_ORIGIN', 'FIRE_DETECTOR', 'NFDRS_FUEL_MODEL', 'COVER_CLASS', 'ASPECT']
DERIVED_FEATURES = ['DISCOVERY_MONTH', 'DISCOVERY_DOY', 'DISCOVERY_HOUR']
FEATURES = DERIVED_FEATURES + NUMERIC_FEATURES + CATEGORICAL_FEATURES
RAW_FEATURES = NUMERIC_FEATURES + CATEGORICAL_FEATURES
REQUIRED_SOURCE = [ID_COL, TIME_COL, PRESCRIBED, TOTAL] + RAW_FEATURES
OUTPUT_COLUMNS = [ID_COL, TIME_COL] + FEATURES + [TARGET]


def _read_header(path):
    try:
        return list(pd.read_csv(path, nrows=0, encoding='utf-8-sig').columns)
    except Exception:
        return []


def _looks_like_csv(path):
    try:
        with open(path, 'rb') as fh:
            head = fh.read(8192).lstrip()
        return bool(head) and not head.startswith((b'{', b'[', b'<', b'PK'))
    except Exception:
        return False


def _read_csv(path):
    columns = _read_header(path)
    missing = [c for c in REQUIRED_SOURCE if c not in columns]
    if missing:
        raise ValueError('missing source columns: ' + ','.join(missing))
    chunks = []
    for chunk in pd.read_csv(path, usecols=REQUIRED_SOURCE, dtype=str, chunksize=100000, keep_default_na=True, encoding='utf-8-sig', low_memory=False):
        chunks.append(chunk)
    if not chunks:
        raise ValueError('empty CSV')
    return pd.concat(chunks, ignore_index=True), columns


def _read_rest(cache):
    frames = []
    offset = 0
    fields = ','.join(REQUIRED_SOURCE)
    where = 'DISCOVER_YEAR>=1987 AND DISCOVER_YEAR<=2019'
    while offset <= 400000:
        params = {'where': where, 'outFields': fields, 'returnGeometry': 'false', 'f': 'json', 'resultRecordCount': '2000', 'resultOffset': str(offset), 'orderByFields': 'OBJECTID'}
        url = REST_URL + '?' + urlencode(params)
        path = fetch(url, cache, 'firestat_rest_' + str(offset) + '.json')
        with open(path, 'r', encoding='utf-8') as fh:
            payload = json.load(fh)
        feats = payload.get('features') or []
        if not feats:
            break
        frames.append(pd.DataFrame([f.get('attributes', {}) for f in feats]))
        offset += len(feats)
        if len(feats) < 2000:
            break
    if not frames:
        raise ValueError('REST fallback returned no features')
    return pd.concat(frames, ignore_index=True), list(REQUIRED_SOURCE)


def _load(cache):
    cache = Path(cache)
    cache.mkdir(parents=True, exist_ok=True)
    path = Path(fetch(SOURCE_URL, cache, 'firestat_occurrence.csv'))
    from_rest = False
    if _looks_like_csv(path):
        try:
            df, columns = _read_csv(path)
        except Exception:
            df, columns = _read_rest(cache)
            from_rest = True
    else:
        df, columns = _read_rest(cache)
        from_rest = True
    return df, columns, from_rest, path


def _clean_strings(df):
    for c in REQUIRED_SOURCE:
        if c in df.columns:
            df[c] = df[c].astype('string').str.strip()
    return df


def _parse_time(df, from_rest):
    s = df[TIME_COL]
    if from_rest:
        num = pd.to_numeric(s, errors='coerce')
        dt = pd.to_datetime(num, unit='ms', errors='coerce', utc=True)
    else:
        dt = pd.to_datetime(s, errors='coerce', utc=True)
    return dt.dt.tz_convert(None)


def _normalize(df, from_rest):
    df = _clean_strings(df.copy())
    df['_dt'] = _parse_time(df, from_rest)
    df = df[df['_dt'].notna()].copy()
    df = df[(df['_dt'].dt.year >= 1987) & (df['_dt'].dt.year <= 2019)].copy()
    pres = df[PRESCRIBED].astype('string').str.strip().str.upper()
    pres = pres.replace({'NULL': pd.NA, 'NONE': pd.NA, '': pd.NA})
    mask = (pres.isna() | pres.eq('N')).fillna(False)
    df = df[mask].copy()
    df[TOTAL] = pd.to_numeric(df[TOTAL], errors='coerce')
    negative_acres = int((df[TOTAL] < 0).sum())
    df = df[df[TOTAL].notna() & (df[TOTAL] >= 0)].copy()
    df[TARGET] = (df[TOTAL] > 100.0).astype('int8')
    for c in NUMERIC_FEATURES:
        df[c] = pd.to_numeric(df[c], errors='coerce')
    for c in CATEGORICAL_FEATURES:
        df[c] = df[c].astype('string').str.strip()
    for c in ['STATE_CODE', 'OWNERSHIP_AGENCY_AT_ORIGIN', 'PROTECTING_AGENCY_AT_ORIGIN', 'FIRE_DETECTOR', 'NFDRS_FUEL_MODEL', 'COVER_CLASS', 'ASPECT']:
        df[c] = df[c].str.upper()
    df['DISCOVERY_MONTH'] = df['_dt'].dt.month.astype('Int64')
    df['DISCOVERY_DOY'] = df['_dt'].dt.dayofyear.astype('Int64')
    df['DISCOVERY_HOUR'] = df['_dt'].dt.hour.astype('Int64')
    df[TIME_COL] = df['_dt'].dt.strftime('%Y-%m-%dT%H:%M:%S')
    return df, negative_acres


def _split_frames(df):
    windows = {'train': ('1987-01-01', '2015-01-01'), 'eval': ('2015-01-01', '2018-01-01'), 'holdout': ('2018-01-01', '2020-01-01')}
    frames = {}
    for name, (start, end) in windows.items():
        mask = pd.Series(True, index=df.index)
        if start is not None:
            mask &= df['_dt'] >= pd.Timestamp(start)
        if end is not None:
            mask &= df['_dt'] < pd.Timestamp(end)
        frames[name] = df[mask].copy()
    return frames, windows


def _prepare(df):
    out = df[OUTPUT_COLUMNS].copy()
    out[TARGET] = out[TARGET].astype('int8')
    return out.sort_values([TIME_COL, ID_COL], kind='mergesort', na_position='last')


def build(output, cache):
    output = Path(output)
    cache = Path(cache)
    public = output / 'public'
    private = output / 'private'
    public.mkdir(parents=True, exist_ok=True)
    private.mkdir(parents=True, exist_ok=True)
    cache.mkdir(parents=True, exist_ok=True)
    df, source_columns, from_rest, source_path = _load(cache)
    df, negative_acres = _normalize(df, from_rest)
    checks = []

    def add(check, observed, expected, passed, kind=None):
        item = {'check': check, 'observed': str(observed), 'expected': str(expected), 'passed': bool(passed)}
        if kind is not None:
            item['kind'] = kind
        checks.append(item)

    missing = [c for c in REQUIRED_SOURCE if c not in source_columns]
    add('required FIRESTAT columns present', 'missing=' + str(missing), 'OBJECTID, DISCOVERY, PRESCRIBED_FIRE, TOTAL_ACRES_BURNED and all declared feature fields', not missing)

    n_rows = int(len(df))
    n_pos = int(df[TARGET].sum())
    duplicate_ids = int(df[ID_COL].duplicated().sum())
    min_dt = df['_dt'].min()
    max_dt = df['_dt'].max()
    dt_ok = bool(pd.notna(min_dt) and pd.notna(max_dt) and min_dt >= pd.Timestamp('1987-01-01') and max_dt < pd.Timestamp('2020-01-01'))
    add('source loaded and DISCOVERY parses into 1987-2019', 'source=' + ('REST' if from_rest else 'CSV') + '; rows=' + str(n_rows) + '; range=' + str(min_dt) + '..' + str(max_dt), 'nonempty source and discovery timestamps in 1987-01-01T00:00:00..2019-12-31T23:59:59', n_rows > 0 and dt_ok)

    prescribed_values = sorted([str(v).upper() for v in df[PRESCRIBED].dropna().unique()])
    add('PRESCRIBED_FIRE excludes prescribed fires', prescribed_values, 'only null or N after filter', not prescribed_values or set(prescribed_values).issubset({'N'}))

    total_min = float(df[TOTAL].min()) if n_rows else float('nan')
    total_max = float(df[TOTAL].max()) if n_rows else float('nan')
    add('TOTAL_ACRES_BURNED is nonnegative acres', 'min=' + str(total_min) + '; max=' + str(total_max) + '; negative_dropped=' + str(negative_acres), 'acres field, nonnegative finite values', bool(n_rows and total_min >= 0 and np.isfinite(total_max)), kind='unit')

    prevalence = 100.0 * n_pos / n_rows if n_rows else float('nan')
    add('100-acre target threshold and prevalence', 'positives=' + str(n_pos) + '; prevalence=' + str(round(prevalence, 2)) + '%', '10,156 positives of 306,733 eligible rows, about 3.31%', n_pos == 10156 and abs(prevalence - 3.31) <= 0.01, kind='unit')

    add('eligible unplanned 1987-2019 rows', n_rows, 306733, n_rows == 306733)
    add('OBJECTID uniqueness', duplicate_ids, 0, duplicate_ids == 0)

    target_values = sorted(int(v) for v in df[TARGET].dropna().unique())
    add('binary target values', target_values, '[0, 1]', target_values == [0, 1])

    def _has_example(unit, year, acres):
        m = df['REPORT_UNIT_NAME'].astype('string').str.contains(unit, regex=False, na=False)
        m &= df['_dt'].dt.year.eq(year)
        sub = df[m]
        if len(sub) == 0:
            return False
        return bool((sub[TOTAL] - acres).abs().le(0.01).any())

    hawk = _has_example('HAWK LANE SCHOOL', 1997, 37.0)
    white = _has_example('WHITE ROCK', 1997, 1.0)
    add('published source examples', 'HAWK LANE SCHOOL 1997 total=37.0: ' + str(hawk) + '; WHITE ROCK 1997 total=1.0: ' + str(white), 'both example rows present with documented acreage', hawk and white)

    frames, windows = _split_frames(df)
    counts = {k: int(len(v)) for k, v in frames.items()}
    positives = {k: int(v[TARGET].sum()) for k, v in frames.items()}
    expected_counts = {'train': 275269, 'eval': 20292, 'holdout': 11172}
    expected_pos = {'train': 8465, 'eval': 1146, 'holdout': 545}
    add('frozen split row counts', counts, expected_counts, counts == expected_counts)
    add('frozen split positive counts', positives, expected_pos, positives == expected_pos)
    add('all rows assigned to exactly one split', sum(counts.values()), n_rows, sum(counts.values()) == n_rows)

    forbidden = [TOTAL, 'FIRE_SIZE_CLASS', 'AGENCY_ACRES', 'OTHER_ACRES_INSIDE', 'OTHER_ACRES_OUTSIDE', 'WUI_ACRES', 'PRESCRIBED_ACRES', 'FIRE_OUT', 'STRATEGY_MET', 'CONTAINED', 'COMPLEX_FIRE', 'COMPLEX_NAME', 'FIRE_INTENSITY_LEVEL', 'INITIAL_RESPONSE', 'STATISTICAL_CAUSE', 'INITIAL_STRATEGY']
    add('output columns exclude label source and post-hoc fields', ','.join(OUTPUT_COLUMNS), 'declared ID, DISCOVERY, declared features and target only', not any(c in OUTPUT_COLUMNS for c in forbidden))
    add('target header exact', TARGET, 'large_fire', TARGET == 'large_fire')

    failed = [c for c in checks if not c['passed']]
    assert not failed, 'source checks failed: ' + json.dumps(failed, indent=2)

    paths = {'train': public / 'train.csv', 'eval': public / 'eval.csv', 'holdout': private / 'holdout.csv'}
    for name in ['train', 'eval', 'holdout']:
        _prepare(frames[name]).to_csv(paths[name], index=False, na_rep='', lineterminator=chr(10))

    headers = {}
    for name, path in paths.items():
        headers[name] = list(pd.read_csv(path, nrows=0, encoding='utf-8-sig').columns)
    add('written CSV headers identical and exact', headers, OUTPUT_COLUMNS, all(h == OUTPUT_COLUMNS for h in headers.values()))

    failed = [c for c in checks if not c['passed']]
    assert not failed, 'output checks failed: ' + json.dumps(failed, indent=2)
    return checks
